"""G021: score each cell's results.csv (scripts/ab_window.sh output) as pre-registered.

Per cell: for wall_s, cpu_s, peak_anon_MB and post_idle_anon_MB, the median of each arm's 3 runs with the range,
the ratio of medians n9/stock, and "no overlap" when each arm's runs all lie on one side of the other's.
Also: runs per arm, hash_match on every run, and the blocks each run added (end_h - start_h).
usage: g021_score.py <cell dir>...   (each holds results.csv; the cell name is the dir name)
"""
import csv, os, statistics, sys

BANDS = {  # (wall, cpu, peak anon) bands from the README, None where none was set
    "small_t24": ((0.80, 0.97), (0.30, 0.50), None), "small_t12": ((0.85, 1.03), (0.45, 0.68), None),
    "heavy_t24": ((0.30, 0.50), (0.10, 0.25), (0.15, 0.30)), "heavy_t12": ((0.35, 0.55), (0.18, 0.35), (0.22, 0.40)),
    "onein_t24": ((0.45, 0.70), (0.60, 0.80), None), "onein_t12": ((0.50, 0.75), (0.60, 0.80), None),
}
FIG = ("wall_s", "cpu_s", "peak_anon_MB", "post_idle_anon_MB")

all_hash = True
for d in sys.argv[1:]:
    cell = os.path.basename(d.rstrip("/")).replace("g021_", "")
    rows = list(csv.DictReader(open(os.path.join(d, "results.csv"))))
    arms = {a: [r for r in rows if r["arm"] == a] for a in ("stock", "n9")}
    hashes = all(r["hash_match"] == "yes" for r in rows)
    all_hash &= hashes and all(len(v) == 3 for v in arms.values())
    print("== %s: runs stock %d, n9 %d; hash_match all: %s; blocks stock %s, n9 %s" % (
        cell, len(arms["stock"]), len(arms["n9"]), "yes" if hashes else "NO",
        ",".join(r["blocks"] for r in arms["stock"]), ",".join(r["blocks"] for r in arms["n9"])))
    bands = BANDS.get(cell, (None, None, None))
    for i, k in enumerate(FIG):
        s = [float(r[k]) for r in arms["stock"]]; n = [float(r[k]) for r in arms["n9"]]
        ms, mn = statistics.median(s), statistics.median(n)
        ratio = mn / ms
        disjoint = max(n) < min(s) or max(s) < min(n)
        band = bands[i] if i < 3 else None
        bt = "" if band is None else "; band %.2f-%.2f: %s" % (band[0], band[1], "met" if band[0] <= ratio <= band[1] else "MISSED")
        print("  %-18s stock %6.0f (%.0f-%.0f)  n9 %6.0f (%.0f-%.0f)  n9/stock %.3f (%+.1f%%), %s%s" % (
            k, ms, min(s), max(s), mn, min(n), max(n), ratio, 100 * (ratio - 1), "no overlap" if disjoint else "overlap", bt))
print("prediction 8, all 36 runs present and on .22's hash: %s" % ("yes" if all_hash and len(sys.argv) == 7 else "NO"))
